contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 tokenId, uint256 burnAmount, uint256 mintQuantity, uint256 itemPrice, uint16 dailyAllowance) public {
        require(burnAmount > 0);
        require(mintQuantity >= burnAmount);

        c.createGameItem("TestItem", "uri", false, true, 0, itemPrice, dailyAllowance); if (__ESBMC_reverted()) return;

        c.mint(tokenId, mintQuantity); if (__ESBMC_reverted()) return;

        uint256 balanceBefore = c.balanceOf(address(this), tokenId); if (__ESBMC_reverted()) return;

        c.burn(address(this), tokenId, burnAmount); if (__ESBMC_reverted()) return;

        uint256 balanceAfter = c.balanceOf(address(this), tokenId); if (__ESBMC_reverted()) return;

        assert(balanceAfter == balanceBefore - burnAmount);
    }

    receive() external payable {}
}

