pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {GameItems} from "../src/GameItems.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    GameItems c;

    function setUp() public {
        c = new GameItems(address(this), address(this));
    }

    function _run(uint256 tokenId, uint256 burnAmount, uint256 mintQuantity, uint256 itemPrice, uint16 dailyAllowance) internal {
        vm.assume(burnAmount > 0);
        vm.assume(mintQuantity >= burnAmount);
        try c.createGameItem("TestItem", "uri", false, true, 0, itemPrice, dailyAllowance) {} catch { return; }
        try c.mint(tokenId, mintQuantity) {} catch { return; }
        uint256 balanceBefore;
        try c.balanceOf(address(this), tokenId) returns (uint256 __r) { balanceBefore = __r; } catch { return; }
        try c.burn(address(this), tokenId, burnAmount) {} catch { return; }
        uint256 balanceAfter;
        try c.balanceOf(address(this), tokenId) returns (uint256 __r) { balanceAfter = __r; } catch { return; }
        assertTrue(balanceAfter == balanceBefore - burnAmount);
    }

    function testFuzz_run(uint256 tokenId, uint256 burnAmount, uint256 mintQuantity, uint256 itemPrice, uint16 dailyAllowance) public {
        _run(tokenId, burnAmount, mintQuantity, itemPrice, dailyAllowance);
    }

    receive() external payable {}
}
